// Aviso del trabajador: { event: 'google.review.received', tenantId, review: {...} }.
// El cuerpo llega en la raiz; se admite tambien bajo 'body' porque el nodo Webhook no siempre
// envuelve igual segun como se publique el flujo.
const entrada = $input.first().json ?? {};
const aviso = entrada.body ?? entrada;
const resena = aviso.review ?? {};

const rating = Number(resena.rating ?? 0);
const nombre = String(resena.reviewer_name ?? '').trim();
const providerReviewId = String(resena.provider_review_id ?? '').trim();

if (!providerReviewId) {
  throw new Error('El aviso llego sin identificador de resena: no se puede responder ni derivar.');
}

// Google guarda UNA sola respuesta del propietario. Si la resena ya tiene respuesta -- porque una
// persona la contesto a mano en Google -- este flujo no publica nada.
const yaRespondida = Boolean(resena.replied_at);

return [{
  json: {
    provider_review_id: providerReviewId,
    rating,
    reviewer_name: nombre,
    resena_texto: String(resena.body ?? ''),
    ya_respondida: yaRespondida,
    responder_automatico: !yaRespondida && rating >= 4,
    derivar_a_asesor: !yaRespondida && rating > 0 && rating <= 3,
  },
}];

const r = $input.first().json || {};
let b = r.body ?? r;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch { b = {}; } }
const status = Number(r.statusCode ?? 0);
const publicada = !r.error && status >= 200 && status < 300 && b.source === 'bot';

if (!publicada) {
  const motivo = String(b.message ?? r.error?.message ?? 'sin detalle').replace(/https?:\/\/\S+/g, '[URL]').slice(0, 300);
  throw new Error('No se pudo publicar la respuesta de la resena (' + (status || 'sin respuesta') + '): ' + motivo);
}

return [{ json: { ...$('Leer aviso de reseña').first().json, respuesta_publicada: true, respondida_en: b.repliedAt ?? null } }];

const r = $input.first().json || {};
let b = r.body ?? r;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch { b = {}; } }
const status = Number(r.statusCode ?? 0);
const derivada = !r.error && status >= 200 && status < 300 && Boolean(b.routedToHumanAt);

if (!derivada) {
  const motivo = String(b.message ?? r.error?.message ?? 'sin detalle').replace(/https?:\/\/\S+/g, '[URL]').slice(0, 300);
  throw new Error('No se pudo derivar la resena (' + (status || 'sin respuesta') + '): ' + motivo);
}

return [{ json: { ...$('Leer aviso de reseña').first().json, derivada_al_asesor: true, derivada_en: b.routedToHumanAt } }];
